from .core import word_count, top_words, tokenize


def build_report(text):
    """Build a statistics report for the given text."""
    tokens = tokenize(text)
    distinct_count = len(set(tokens))

    return {
        'word_count': word_count(text),
        'distinct_words': distinct_count,
        'top_words': top_words(text)
    }
